@sig trait ConditionIndicationQualification_Api {
  def id: Art.BridgeId
  def condition_sample_Id : Art.PortId
  def assessment_to_compatibility_Id : Art.PortId
  def assessment_to_arbiter_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var assessment_to_compatibility: Vehicle_Controller_Mode_Coordinator.ConditionAssessment.Type = $

  def put_assessment_to_compatibility(value : Vehicle_Controller_Mode_Coordinator.ConditionAssessment.Type) : Unit = {
    Contract(
      Modifies(assessment_to_compatibility),
      Ensures(
        assessment_to_compatibility == value
      )
    )
    Spec {
      assessment_to_compatibility = value
    }

    Art.putValue(assessment_to_compatibility_Id, Vehicle_Controller_Mode_Coordinator.ConditionAssessment_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var assessment_to_arbiter: Vehicle_Controller_Mode_Coordinator.ConditionAssessment.Type = $

  def put_assessment_to_arbiter(value : Vehicle_Controller_Mode_Coordinator.ConditionAssessment.Type) : Unit = {
    Contract(
      Modifies(assessment_to_arbiter),
      Ensures(
        assessment_to_arbiter == value
      )
    )
    Spec {
      assessment_to_arbiter = value
    }

    Art.putValue(assessment_to_arbiter_Id, Vehicle_Controller_Mode_Coordinator.ConditionAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ConditionIndicationQualification_Initialization_Api (
  val id: Art.BridgeId,
  val condition_sample_Id : Art.PortId,
  val assessment_to_compatibility_Id : Art.PortId,
  val assessment_to_arbiter_Id : Art.PortId) extends ConditionIndicationQualification_Api

@datatype class ConditionIndicationQualification_Operational_Api (
  val id: Art.BridgeId,
  val condition_sample_Id : Art.PortId,
  val assessment_to_compatibility_Id : Art.PortId,
  val assessment_to_arbiter_Id : Art.PortId) extends ConditionIndicationQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var condition_sample: Vehicle_Controller_Mode_Coordinator.ConditionSample = $

  def get_condition_sample() : Option[Vehicle_Controller_Mode_Coordinator.ConditionSample] = {
    Contract(
      Ensures(
        Res == Some(condition_sample)
      )
    )
    val value : Option[Vehicle_Controller_Mode_Coordinator.ConditionSample] = Art.getValue(condition_sample_Id) match {
      case Some(Vehicle_Controller_Mode_Coordinator.ConditionSample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port condition_sample.  Expecting 'Vehicle_Controller_Mode_Coordinator.ConditionSample_Payload' but received ${v}")
        None[Vehicle_Controller_Mode_Coordinator.ConditionSample]()
      case _ => None[Vehicle_Controller_Mode_Coordinator.ConditionSample]()
    }
    return value
  }
}
